<?php
require_once 'auth.php'; require_login(); require_once 'config.php'; $pdo=db(); $msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)($_POST['id']??0);if($id){$s=$pdo->prepare("UPDATE laptops SET laptop_number=?,model=?,serial_number=? WHERE id=?");$s->execute([trim($_POST['laptop_number']),trim($_POST['model']),trim($_POST['serial_number']),$id]);$msg='Laptop updated.';}else{$s=$pdo->prepare("INSERT INTO laptops(laptop_number,model,serial_number) VALUES(?,?,?)");$s->execute([trim($_POST['laptop_number']),trim($_POST['model']),trim($_POST['serial_number'])]);$msg='Laptop added.';}}catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM laptops WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query("SELECT * FROM laptops ORDER BY laptop_number")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><title>Laptops</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include 'partials/nav.php';?><main class="container"><h1>Laptops</h1><?php if($msg):?><div class="alert success"><?=$msg?></div><?php endif;?><?php if($err):?><div class="alert error"><?=htmlspecialchars($err)?></div><?php endif;?>
<div class="card"><h2><?= $edit?'Edit Laptop':'Add Laptop'?></h2><form method="post" class="grid"><input type="hidden" name="id" value="<?=htmlspecialchars($edit['id']??0)?>"><label>Laptop Number<input name="laptop_number" required value="<?=htmlspecialchars($edit['laptop_number']??'')?>"></label><label>Model<input name="model" required value="<?=htmlspecialchars($edit['model']??'')?>"></label><label>Serial Number<input name="serial_number" value="<?=htmlspecialchars($edit['serial_number']??'')?>"></label><div><button class="btn primary">Save Laptop</button></div></form></div>
<div class="card"><h2>Laptop Records</h2><div class="table-wrap"><table><tr><th>Number</th><th>Model</th><th>Serial</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['laptop_number']?></td><td><?=htmlspecialchars($r['model'])?></td><td><?=htmlspecialchars($r['serial_number'])?></td><td><?=$r['status']?></td><td><a class="btn small" href="?edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div></div></main></body></html>
